def apply(rel, txt):
    crlf = "\r\n" in txt
    t = txt.replace("\r\n", "\n")
    if rel == "snippet:x-owner-wizard":
        if _sha(t) == OWNER_NEW_SHA256:
            raise SystemExit("had256_release: snippet 707 is already this x-owner-wizard")
        if _sha(t) != OWNER_BASE_SHA256:
            raise SystemExit("had256_release: snippet 707 is " + _sha(t)[:12] + ", not the 1.0.0 base " + OWNER_BASE_SHA256[:12] + " (drift: stop)")
        out = owner_code()
    elif rel == "snippet:x-broker-drop":
        if "define( 'NL_DROP_VERSION', '1.1.4' )" in t or "function nl_drop_lock_acquire(" in t:
            raise SystemExit("had256_release: x-broker-drop already carries the HAD-256 hunks")
        if _sha(t) != BROKER_BASE_SHA256:
            print("had256_release: x-broker-drop is " + _sha(t)[:12] + ", not the 1.1.3 base " + BROKER_BASE_SHA256[:12] + "; applying by anchors")
        for i, (old, new) in enumerate(HUNKS, 1):
            n = t.count(old)
            if n != 1:
                raise SystemExit("had256_release: x-broker-drop hunk " + str(i) + " anchor is there " + str(n) + " times")
            t = t.replace(old, new)
        out = t
    else:
        raise SystemExit("had256_release: unknown rel " + rel)
    return out.replace("\n", "\r\n") if crlf else out


if __name__ == "__main__":
    b = apply("snippet:x-broker-drop", _code(_show(BASE, 'plugins/nadlan-config/inc/broker-drop.php')))
    assert _sha(b) == BROKER_NEW_SHA256, "x-broker-drop: base + 8 hunks != snapshot 3"
    o = apply("snippet:x-owner-wizard", _code(_show(BASE, 'plugins/nadlan-config/inc/owner-wizard.php')))
    assert _sha(o) == OWNER_NEW_SHA256
    for rel, txt in (("snippet:x-broker-drop", b), ("snippet:x-owner-wizard", o)):
        try:
            apply(rel, txt)
            raise AssertionError(rel + ": a second apply did not stop")
        except SystemExit as e:
            assert "already" in str(e), e
    print("had256_release OK: x-broker-drop " + BROKER_BASE_SHA256[:12] + " -> " + BROKER_NEW_SHA256[:12] + " (8 hunks), snippet 707 " + OWNER_BASE_SHA256[:12] + " -> " + OWNER_NEW_SHA256[:12] + "; a second apply stops")
